        * ticks:               Number of game ticks required per action
        * charm:               Charm used to create a pouch
        * familiar:            Link to related summoning familiar
        * familiarTitle:       Alternative name for summoning familiar
        * familiarIcon:        Image location for summoning familiar pouch icon
        * useXp:               Experience from using a scroll
        * materialName#:       Name of material required
